param([string]$Version)
# Generated by installgen (https://github.com/lovrozagar/installgen). Regenerate it with `installgen build`.
#
#   powershell -c "irm <url> | iex"
#   iex "& {$(irm <url>)} -Version 1.2.3"

& {
	$ErrorActionPreference = 'Stop'
	$ProgressPreference = 'SilentlyContinue'

	$name = @@NAME@@
	$baseUrl = @@BASE_URL@@
	$latestUrl = @@LATEST_URL@@
	$defaultVersion = @@DEFAULT_VERSION@@
	$tagPrefix = @@TAG_PREFIX@@
	$installDir = $env:@@ENV_PREFIX@@_INSTALL_DIR
	if (-not $installDir) { $installDir = @@INSTALL_DIR@@ }
	$installDirDisplay = @@INSTALL_DIR_DISPLAY@@
	$modifyPath = @@MODIFY_PATH@@
	if ($env:@@ENV_PREFIX@@_NO_MODIFY_PATH) { $modifyPath = $false }
	$requested = if ($Version) { $Version } else { $env:@@ENV_PREFIX@@_VERSION }
	$message = @@MESSAGE@@
	$shUrl = @@SH_URL@@
	$ps1Url = @@PS1_URL@@
	$platforms = @@PLATFORMS@@

	$ver = ''
	$tag = ''
	$platform = ''
	switch ($platform) {
@@PLATFORM_CASES@@
	}

	Write-Output "$name $baseUrl $latestUrl $defaultVersion $tagPrefix $installDir $installDirDisplay"
	Write-Output "$modifyPath $requested $message $shUrl $ps1Url $platforms $ver $tag"
}
